// 原完整Interaction保存点覆盖独立opening账；所有NPC原通路仍必须写前拒绝本人专属开场。
#include "known_personal_dialogue_world.hpp"
#include "known_personal_dialogue_control.hpp"
#include "resident/kernel/world_bundle.hpp"
#include "resident/domains/military/military_roster_history.hpp"
#include <limits>
namespace hanmo::resident {namespace {
Status enabled(const WorldBundle& w){if(!w.dynamic_enabled()||!w.catalog->common||!w.catalog->interaction||!w.catalog->family||!w.catalog->known_personal_dialogues||!w.interaction.known_personal_dialogues||!w.family_life_enabled())return common_failure("KnownPersonalDialogueProfileRequired");if(known_personal_dialogue_needs_birth(*w.catalog->known_personal_dialogues)&&(!w.family_birth_enabled()||!w.catalog->family_lineage))return common_failure("KnownPersonalDialogueBirthProfileRequired");return common_success();}
Status player(const WorldBundle& w,const StableId& actor){auto r=command_common_guard(w,actor,"open_known_personal_dialogue");if(!r.ok)return r;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("KnownPersonalDialoguePlayerRequired");}
}
KnownPersonalDialogueWorldAccess::KnownPersonalDialogueWorldAccess(const WorldBundle& w,std::optional<DynamicStepInput> phase):world_(w),phase_(std::move(phase)),deaths_([this](const StableId& actor)->Outcome<std::optional<FamilyDeathOrigin>>{auto source=phase_?query_military_actor_death(world_.common,world_.military,actor,*phase_):query_military_actor_death(world_.common,world_.military,actor);if(!source.ok)return {false,{},source.error};if(!source.value)return {true,std::nullopt,{}};const auto& d=*source.value;return {true,FamilyDeathOrigin{d.actor_id,d.casualty_fact_id,d.battle_id,d.tick},{}};}),sources_{
 [this](const StableId& actor)->Outcome<std::optional<BornActorSource>>{if(phase_)return {false,{},common_failure("KnownPersonalDialogueHistoryOnly").error};if(!world_.family_birth_enabled()||!world_.catalog->family_lineage)return {true,std::nullopt,{}};return read_born_actor_source(world_.common,*world_.catalog->common,*world_.catalog->family_lineage,world_.family_birth,deaths_,actor);},
 [this](const StableId& actor,Integer tick,const StableId& fact)->Outcome<std::optional<BornActorSource>>{if(!world_.family_birth_enabled()||!world_.catalog->family_lineage)return {true,std::nullopt,{}};return phase_?read_born_actor_source_before_fact(world_.common,*world_.catalog->common,*world_.catalog->family_lineage,world_.family_birth,deaths_,actor,tick,fact,*phase_):read_born_actor_source_before_fact(world_.common,*world_.catalog->common,*world_.catalog->family_lineage,world_.family_birth,deaths_,actor,tick,fact);},
 [this](const StableId& actor)->Outcome<ActorPresenceRead>{if(phase_)return {false,{},common_failure("KnownPersonalDialogueHistoryOnly").error};return read_actor_presence(world_.common,*world_.catalog->common,deaths_,actor);},
 [this](const StableId& actor,Integer tick,const StableId& fact){return read_actor_presence_before_fact(world_.common,*world_.catalog->common,deaths_,actor,tick,fact,phase_?&*phase_:nullptr);},
 [this](Integer tick,const StableId& fact){return known_personal_dialogue_player_before(world_.common,world_.family,world_.family_legacy_enabled()?&world_.family_legacy:nullptr,tick,fact);}
},interaction_(w.services.interaction_access()),context_{w.common,w.interaction,*w.interaction.known_personal_dialogues,*w.catalog->interaction,*w.catalog->known_personal_dialogues,*w.catalog->family,w.catalog->family_birth?*w.catalog->family_birth:empty_birth_,interaction_,sources_},read_(context_){}
Outcome<std::shared_ptr<KnownPersonalDialogueWorldAccess>> KnownPersonalDialogueWorldAccess::create(const WorldBundle& w){auto r=enabled(w);if(!r.ok)return {false,{},r.error};return {true,std::shared_ptr<KnownPersonalDialogueWorldAccess>(new KnownPersonalDialogueWorldAccess(w)),{}};}
// 身份源仍止于from。阶段仅让已实际出现的to死因通过原纯读，后来死亡不倒抹旧会面。
Outcome<std::shared_ptr<KnownPersonalDialogueWorldAccess>> KnownPersonalDialogueWorldAccess::create_for_phase_history(const WorldBundle& w,const DynamicStepInput& phase){auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};if(w.common.tick()<0||w.common.tick()==std::numeric_limits<Integer>::max()||phase.from_tick!=w.common.tick()||phase.to_tick!=phase.from_tick+1)return {false,{},common_failure("KnownPersonalDialogueHistoryPhaseInvalid").error};return {true,std::shared_ptr<KnownPersonalDialogueWorldAccess>(new KnownPersonalDialogueWorldAccess(w,phase)),{}};}
Outcome<bool> match_known_personal_dialogue_session_world(const WorldBundle& w,const InteractionSession& s){if(!w.catalog->known_personal_dialogues&&!w.interaction.known_personal_dialogues)return {true,false,{}};auto r=enabled(w);if(!r.ok)return {false,{},r.error};return match_known_personal_dialogue_session(w.common,*w.interaction.known_personal_dialogues,*w.catalog->known_personal_dialogues,*w.catalog->interaction,s);}
Status validate_known_personal_dialogue_world(const WorldBundle& w){const auto* state=w.interaction.known_personal_dialogues?&*w.interaction.known_personal_dialogues:nullptr;auto r=validate_known_personal_dialogue_layout(w.common,w.catalog->identity.module_versions,w.catalog->known_personal_dialogues.get(),state);if(!r.ok)return r;if(state){auto holder=KnownPersonalDialogueWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};r=validate_known_personal_dialogues(holder.value->context());if(!r.ok)return r;}return validate_known_personal_dialogue_cached_results(w.common,state);}
Outcome<KnownPersonalDialogueQuote> prepare_known_personal_dialogue_world(const WorldBundle& w,const StableId& actor,const OpenKnownPersonalDialogue& request){auto r=player(w,actor);if(!r.ok)return {false,{},r.error};auto holder=KnownPersonalDialogueWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};return preview_known_personal_dialogue(holder.value->context(),actor,request);}
Outcome<InteractionEffect> commit_known_personal_dialogue_world(WorldBundle& w,const StableId& actor,const OpenKnownPersonalDialogue& request,const KnownPersonalDialogueQuote& quote){auto r=player(w,actor);if(!r.ok)return {false,{},r.error};auto holder=KnownPersonalDialogueWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};auto result=open_known_personal_dialogue_in_candidate(w.common,w.interaction,*w.interaction.known_personal_dialogues,holder.value->context(),actor,request,quote);if(!result.ok)return {false,{},result.error};InteractionEffect effect;effect.settlement_result=result.value;return {true,std::move(effect),{}};}
Outcome<BoundaryValue> query_known_personal_dialogue_world(const WorldBundle& w,Integer cursor){auto holder=KnownPersonalDialogueWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};return query_known_personal_dialogues(holder.value->context(),cursor);}
Outcome<StableId> known_personal_dialogue_new_result_world(const WorldBundle& before,const WorldBundle& after,const StableId& actor,const StableId& kind,const ReceiptDetails& details){return known_personal_dialogue_new_player_source(before.interaction.known_personal_dialogues?&*before.interaction.known_personal_dialogues:nullptr,after.interaction.known_personal_dialogues?&*after.interaction.known_personal_dialogues:nullptr,actor,kind,details,after.common.tick());}
Status bind_known_personal_dialogue_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& result){if(!w.interaction.known_personal_dialogues)return source.empty()?common_success():common_failure("KnownPersonalDialogueProfileRequired");return bind_known_personal_dialogue_player_result(w.common,*w.interaction.known_personal_dialogues,source,actor,request,result);}
}
